// TH16 v1.00a Stage 3 midboss, st03mbs.ecl.txt MBoss1:58-162 (entry MBoss1, dep MBoss1_at).
// Source clock zero = MBoss:11 timerReset. Segment window 1380 frames (MBoss:28/34 slot 1),
// ending at MBossDead / MBossCard1 / MBossEscape; target ends on the phase timer.

const TIME_LIMIT: int = 1504;
const OPENING_BUFFER: int = 120;

// TH16 type 8 = rice ball, colors 4 and 6 (source etSprite(0,8,4), etSprite(1,8,6)).
const TH16_RICE: int = 480;
const RICE_COLOR_A: int = 4;
const RICE_COLOR_B: int = 6;

// ---- Source MBoss:41 moveLimit(0,128,280,256): x in [-140,140], y in [0,256].
// moveRand direction bands are the inner quarter: x +-70, y 64..192.
// Helper adapted from the approved TH16 moveRand recipe: speed falls 1.0 -> 0 linearly
// over 60 ticks; bounds are applied per tick so wall contact does not accumulate.
// self_int(0) = next movement step, self_fx(0/1) = logical unit direction.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

// Source moveRand(60, 0, 1.0f): one signed direction sample per call.
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard (0.05 rad); values are unwrapped BAM ints.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Arm the next source movement tick after every wait inside the moveRand window.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// Source MBoss1_at: two fixed-direction fans, alternated every 5 (4 on Lunatic) frames.
async sub mboss1_at() {
    var rank: int = global(GVAR_RANK);
    var count: int = 3;
    if rank == 1 { count = 10; }
    if rank >= 2 { count = 14; }
    var gap: int = 5;
    if rank >= 3 { gap = 4; }
    var speed0: fx = 2fx;
    var speed1: fx = 1fx;
    if rank >= 3 {
        speed0 = 3fx;
        speed1 = 2fx;
    }

    // etNew(0); etAim(0,1); etSprite(0,8,4); etCount(0,N,1); etSpeed(0,s,1.0) with M=1;
    // etDist(0,64) plus the retained ANIM(a=1) retreat of 4*speed along the bullet angle.
    sh_reset(0);
    sh_sprite(0, TH16_RICE, RICE_COLOR_A);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, count, 1);
    sh_speed(0, speed0, 0fx);
    sh_dist(0, 64fx - 4fx * speed0);

    // etNew(1); etAim(1,1); etSprite(1,8,6); etCount(1,N,1); etSpeed(1,s,1.0);
    // etDist(1,16) with the same 4*speed ANIM retreat.
    sh_reset(1);
    sh_sprite(1, TH16_RICE, RICE_COLOR_B);
    sh_aim(1, 0);
    sh_ring(1, 0);
    sh_count(1, count, 1);
    sh_angle(1, 0deg, 9deg);
    sh_speed(1, speed1, 0fx);
    sh_dist(1, 16fx - 4fx * speed1);

    // %A = 3.141593f, %B = 0.0f, $C = 8000; one fire pair per loop body.
    var a: angle = 180deg;
    var b: angle = 0deg;
    for i in 0..8000 {
        sh_angle(0, a, 11deg);       // 0.19198622 rad lane spacing
        sh_fire(0);
        a = a - 10deg;               // %A -= 0.174533 rad
        wait(gap);
        sh_angle(1, b, 9deg);        // 0.15707964 rad lane spacing
        sh_fire(1);
        b = b + 25deg;               // %B += 0.436332 rad
        wait(gap);
    }
}

// Source MBoss entry/state: created at absolute (192,-32), then movePos(0,-64) and
// movePosTime(100, mode4=quad-out, 0,128); MBoss:40 wait(40); MBoss1:61 wait(90);
// MBoss1:62 async emitter; MBoss1:64-69 wait(200) / moveRand(60,0,1.0) / wait(60).
async sub mboss1() {
    set_invuln(65535);
    set_hurtbox(24fx);               // setHurtbox(48,48) circle -> 24
    set_hitbox(20fx);                // setHitbox(40,40) circle -> 20, body contact kept
    move_to(0, 0fx, -64fx, EASE_LINEAR);
    move_to(100, 0fx, 128fx, EASE_QUAD_OUT);
    wait(40);
    wait(90);
    spawn mboss1_at();
    loop {
        card_wait(200);
        card_move_rand();
        card_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var hp: int = 11000;
    if global(GVAR_RANK) >= 2 { hp = 13000; }
    _ = spawn_enemy(192fx, -32fx, hp, 0, 0, 0, mboss1);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
